    await expect(page.getByRole("row", { name: "George Franklin 110 W." })).toContainText("George Franklin");
    await expect(page.getByRole("row", { name: "George Franklin 110 W." })).toContainText("6085551023");
    await page.locator("a[href=\"/petclinic/owners/1\"]").click();
    await expect(page.getByRole("button", { name: "Edit Owner" })).toBeVisible();
    await page.getByRole("button", { name: "Edit Owner" }).click();

    // The edit form must be pre-populated from the owner record before any edit,
